def parse_duration(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError("duration must be a string")

    unit_seconds = {
        "w": 7 * 24 * 60 * 60,
        "d": 24 * 60 * 60,
        "h": 60 * 60,
        "m": 60,
        "s": 1,
    }
    unit_order = {"w": 0, "d": 1, "h": 2, "m": 3, "s": 4}

    total = 0
    last_order = -1
    i = 0
    n = len(s)
    seen_part = False

    while i < n:
        if not ("0" <= s[i] <= "9"):
            raise ValueError("expected a number at the start of a duration part")

        j = i
        while j < n and "0" <= s[j] <= "9":
            j += 1

        if j >= n or s[j] not in unit_seconds:
            raise ValueError("each duration part must have a number followed by a unit")

        unit = s[j]
        j += 1

        order = unit_order[unit]
        if order <= last_order:
            raise ValueError("units must appear in descending order and only once")

        last_order = order
        total += int(s[i:j]) * unit_seconds[unit]
        seen_part = True
        i = j

        if i < n and s[i].isspace():
            i += 1
            while i < n and s[i].isspace():
                i += 1
            if i == n:
                raise ValueError("whitespace is only allowed between duration parts")

    if not seen_part:
        raise ValueError("duration must not be empty or blank")

    return total
