def parse_duration(s: str) -> int:
    # Check for blank input
    if not s.strip():
        raise ValueError("blank input")
    # Reject leading or trailing whitespace
    if s[0].isspace() or s[-1].isspace():
        raise ValueError("leading or trailing whitespace not allowed")

    unit_seconds = {'w': 7 * 24 * 3600, 'd': 24 * 3600, 'h': 3600, 'm': 60, 's': 1}
    unit_rank = {'w': 4, 'd': 3, 'h': 2, 'm': 1, 's': 0}
    valid_units = set(unit_seconds.keys())

    tokens = s.split()

    seen = set()
    prev_rank = None
    total = 0

    for token in tokens:
        if len(token) < 2:
            raise ValueError("token missing number or unit")
        num_str = token[:-1]
        unit = token[-1]
        if not num_str.isdigit():
            raise ValueError("invalid number")
        number = int(num_str)
        if unit not in valid_units:
            raise ValueError("unknown unit")
        if unit in seen:
            raise ValueError("repeated unit")
        unit_rank_val = unit_rank[unit]
        if prev_rank is not None and unit_rank_val > prev_rank:
            raise ValueError("unit out of order")
        prev_rank = unit_rank_val
        seen.add(unit)
        total += number * unit_seconds[unit]

    return total
