def calc(expr: str) -> float:
    expr = expr.strip()
    if not expr:
        raise ValueError("Empty input")

    tokens = []
    i = 0
    while i < len(expr):
        char = expr[i]
        if char.isspace():
            i += 1
            continue
        if char.isdigit() or char == '.':
            num_str = ""
            while i < len(expr) and (expr[i].isdigit() or expr[i] == '.'):
                num_str += expr[i]
                i += 1
            if num_str.count('.') > 1:
                raise ValueError("Invalid number: too many decimal points")
            try:
                tokens.append(float(num_str))
            except ValueError:
                raise ValueError("Invalid number")
        elif char in "+-*/()":
            tokens.append(char)
            i += 1
        else:
            raise ValueError(f"Invalid character: {char}")

    # Check for two numbers in a row (e.g., "1 2")
    for j in range(len(tokens) - 1):
        if isinstance(tokens[j], float) and isinstance(tokens[j+1], float):
            raise ValueError("Two numbers in a row")

    # Convert tokens to handle unary operators
    processed_tokens = []
    for idx, token in enumerate(tokens):
        if token in '+-':
            # Unary if it's the first token or follows an operator or '('
            if idx == 0 or tokens[idx-1] in '+-*/(':
                processed_tokens.append('u+' if token == '+' else 'u-')
            else:
                processed_tokens.append(token)
        else:
            processed_tokens.append(token)

    values = []
    ops = []
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2, 'u+': 3, 'u-': 3}

    def apply_op():
        if not ops:
            return
        op = ops.pop()
        if op == 'u+':
            if not values:
                raise ValueError("Dangling operator")
            # values[-1] remains same
        elif op == 'u-':
            if not values:
                raise ValueError("Dangling operator")
            values[-1] = -values[-1]
        else:
            if len(values) < 2:
                raise ValueError("Dangling operator")
            right = values.pop()
            left = values.pop()
            if op == '+': values.append(left + right)
            elif op == '-': values.append(left - right)
            elif op == '*': values.append(left * right)
            elif op == '/':
                if right == 0:
                    raise ZeroDivisionError("Division by zero")
                values.append(left / right)

    for token in processed_tokens:
        if isinstance(token, float):
            values.append(token)
        elif token == '(':
            ops.append('(')
        elif token == ')':
            while ops and ops[-1] != '(':
                apply_op()
            if not ops:
                raise ValueError("Unbalanced parentheses")
            ops.pop()  # Remove '('
        else:
            # Operator handling: Unary is right-associative, Binary is left-associative
            while (ops and ops[-1] != '(' and
                   (precedence[ops[-1]] > precedence[token] or
                    (precedence[ops[-1]] == precedence[token] and token not in ('u+', 'u-')))):
                apply_op()
            ops.append(token)

    while ops:
        if ops[-1] == '(':
            raise ValueError("Unbalanced parentheses")
        apply_op()

    if len(values) != 1:
        raise ValueError("Malformed expression")

    return values[0]
