import bisect

class IntervalSet:
    def __init__(self):
        # Stores ranges as a sorted list of [start, end) tuples
        self.intervals = []

    def add(self, start, end):
        if start >= end:
            return

        new_intervals = []
        # 1. Ranges that end before the new range starts
        i = 0
        while i < len(self.intervals) and self.intervals[i][1] <= start:
            new_intervals.append(self.intervals[i])
            i += 1

        # 2. Merge overlapping or touching ranges
        m_start, m_end = start, end
        while i < len(self.intervals) and self.intervals[i][0] <= m_end:
            m_start = min(m_start, self.intervals[i][0])
            m_end = max(m_end, self.intervals[i][1])
            i += 1
        new_intervals.append((m_start, m_end))

        # 3. Ranges that start after the new range ends
        while i < len(self.intervals):
            new_intervals.append(self.intervals[i])
            i += 1

        self.intervals = new_intervals

    def remove(self, start, end):
        if start >= end:
            return

        res = []
        for s, e in self.intervals:
            # Case 1: No overlap
            if e <= start or s >= end:
                res.append((s, e))
            else:
                # Case 2: Overlap - keep the parts outside [start, end)
                if s < start:
                    res.append((s, start))
                if e > end:
                    res.append((end, e))
        self.intervals = res

    def contains(self, x):
        # Binary search to find the range that could contain x
        # Find the rightmost range whose start is <= x
        starts = [r[0] for r in self.intervals]
        idx = bisect.bisect_right(starts, x) - 1
        if idx >= 0:
            s, e = self.intervals[idx]
            if s <= x < e:
                return True
        return False

    def ranges(self):
        return self.intervals

    def __len__(self):
        return sum(e - s for s, e in self.intervals)
